            new Quote { Id = "https://en.wikiquote.org/wiki/Galileo_Galilei", Text = "I do not feel obliged to believe that the same God who has endowed us with senses, reason, and intellect has intended us to forgo their use and by some other means to give us knowledge which we can attain by them.", Author = "Galileo Galilei" },
