            new Quote { Id = "https://en.wikiquote.org/wiki/Galileo_Galilei", Text = "All truths are easy to understand once they are discovered; the point is to discover them.", Author = "Galileo Galilei" },
            new Quote { Id = "https://en.wikiquote.org/wiki/Galileo_Galilei", Text = "The Holy Scripture cannot err, and that the decrees therein contained are absolutely true and inviolable. But I should have in your place added that, though Scripture cannot err, its expounders and interpreters are liable to err in many ways; and one error in particular would be most grave and most frequent, if we always stopped short at the literal signification of the words.", Author = "Galileo Galilei" },
            new Quote { Id = "https://en.wikiquote.org/wiki/Galileo_Galilei", Text = "The increase of known truths stimulates the investigation, establishment, and growth of the arts; not their diminution or destruction.", Author = "Galileo Galilei" },
            new Quote { Id = "https://en.wikiquote.org/wiki/Galileo_Galilei", Text = "Nature … is inexorable and immutable; she never transgresses the laws imposed upon her, or cares a whit whether her abstruse reasons and methods of operation are understandable to men.", Author = "Galileo Galilei" },
            new Quote { Id = "https://en.wikiquote.org/wiki/Galileo_Galilei", Text = "The intention of the Holy Ghost is to teach us how one goes to heaven, not how heaven goes.", Author = "Galileo Galilei" },
