            new Quote { Id = "https://en.wikiquote.org/wiki/Galileo_Galilei", Text = "A bucketful of water raised on high and set free, returns to the sea; but who will say that the same water remains heavy in the sea, when being set free there, does not move?", Author = "Galileo Galilei" },
            new Quote { Id = "https://en.wikiquote.org/wiki/Galileo_Galilei", Text = "It always seems to me extreme rashness on the part of some when they want to make human abilities the measure of what nature can do.", Author = "Galileo Galilei" },
            new Quote { Id = "https://en.wikiquote.org/wiki/Galileo_Galilei", Text = "This vain presumption of understanding everything can have no other basis than never understanding anything.", Author = "Galileo Galilei" },
            new Quote { Id = "https://en.wikiquote.org/wiki/Galileo_Galilei", Text = "To apply oneself to great inventions, starting from the smallest beginnings, is no task for ordinary minds; to divine that wonderful arts lie hid behind trivial and childish things is a conception for superhuman talents.", Author = "Galileo Galilei" },
            new Quote { Id = "https://en.wikiquote.org/wiki/Galileo_Galilei", Text = "I consider the earth very noble and admirable precisely because of the diverse alterations, changes, generations, etc. that occur in it incessantly.", Author = "Galileo Galilei" },
            new Quote { Id = "https://en.wikiquote.org/wiki/Galileo_Galilei", Text = "What greater stupidity can be imagined than that of calling jewels, silver, and gold \"precious,\" and earth and soil \"base\"?", Author = "Galileo Galilei" },
            new Quote { Id = "https://en.wikiquote.org/wiki/Galileo_Galilei", Text = "If there were as great a scarcity of soil as of jewels or precious metals, there would not be a prince who would not spend a bushel of diamonds and rubies and a cartload of gold just to have enough earth to plant a jasmine in a little pot, or to sow an orange seed and watch it sprout, grow, and produce its handsome leaves, its fragrant flowers, and fine fruit.", Author = "Galileo Galilei" },
            new Quote { Id = "https://en.wikiquote.org/wiki/Galileo_Galilei", Text = "If you could see the earth illuminated when you were in a place as dark as night, it would look to you more splendid than the moon.", Author = "Galileo Galilei" },
            new Quote { Id = "https://en.wikiquote.org/wiki/Galileo_Galilei", Text = "If what we are discussing were a point of law or of the humanities, in which neither true nor false exists, one might trust in subtlety of mind and readiness of tongue and in the greater experience of the writers, and expect him who excelled in those things to make his reasoning most plausible, and one might judge it to be the best.", Author = "Galileo Galilei" },
            new Quote { Id = "https://en.wikiquote.org/wiki/Galileo_Galilei", Text = "But in the natural sciences, whose conclusions are true and necessary and have nothing to do with human will, one must take care not to place oneself in the defense of error; for here a thousand Demostheneses and a thousand Aristotles would be left in the lurch by every mediocre wit who happened to hit upon the truth for himself.", Author = "Galileo Galilei" },
            new Quote { Id = "https://en.wikiquote.org/wiki/Galileo_Galilei", Text = "Beside themselves with passion, some of them would not be backward even about scheming to suppress and silence their adversaries.", Author = "Galileo Galilei" },
            new Quote { Id = "https://en.wikiquote.org/wiki/Galileo_Galilei", Text = "Among all the great men who have philosophized about this remarkable effect, I am more astonished at Kepler than at any other.", Author = "Galileo Galilei" },
            new Quote { Id = "https://en.wikiquote.org/wiki/Galileo_Galilei", Text = "The sun, with all those planets revolving around it and dependent on it, can still ripen a bunch of grapes as if it had nothing else in the universe to do.", Author = "Galileo Galilei" },
            new Quote { Id = "https://en.wikiquote.org/wiki/Galileo_Galilei", Text = "With regard to those few [propositions] which the human intellect does understand, I believe its knowledge equals the Divine in objective certainty, for here it succeeds in understanding necessity, beyond which there can be no greater sureness.", Author = "Galileo Galilei" },
            new Quote { Id = "https://en.wikiquote.org/wiki/Galileo_Galilei", Text = "I cannot sufficiently admire the eminence of those men's wits, that have received and held it to be true, and with the sprightliness of their judgments offered such violence to their own senses, as that they have been able to prefer that which their reason dictated to them, to that which sensible experiments represented most manifestly to the contrary.", Author = "Galileo Galilei" },
            new Quote { Id = "https://en.wikiquote.org/wiki/Galileo_Galilei", Text = "I cannot find any bounds for my admiration, how that reason was able in Aristarchus and Copernicus, to commit such a rape on their senses, as in despite thereof to make herself mistress of their credulity.", Author = "Galileo Galilei" },
            new Quote { Id = "https://en.wikiquote.org/wiki/Galileo_Galilei", Text = "Who knows but men will reduce me from the profession of a philosopher to that of historian of the Inquisition!", Author = "Galileo Galilei" },
            new Quote { Id = "https://en.wikiquote.org/wiki/Galileo_Galilei", Text = "Let us see how it might be demonstrated that in a finite continuous extension it is not impossible for infinitely many voids to be found.", Author = "Galileo Galilei" },
            new Quote { Id = "https://en.wikiquote.org/wiki/Galileo_Galilei", Text = "If I were again beginning my studies, I should follow the advice of Plato and start with mathematics, a science which proceeds very cautiously and admits nothing as established until it has been rigidly demonstrated.", Author = "Galileo Galilei" },
            new Quote { Id = "https://en.wikiquote.org/wiki/Galileo_Galilei", Text = "There is, in nature, perhaps nothing older than motion, concerning which the books written by philosophers are neither few nor small; nevertheless I have discovered by experiment some properties of it which are worth knowing and which have not hitherto been either observed or demonstrated.", Author = "Galileo Galilei" },
            new Quote { Id = "https://en.wikiquote.org/wiki/Galileo_Galilei", Text = "No one has yet pointed out that this path [of projectiles] is a parabola.", Author = "Galileo Galilei" },
            new Quote { Id = "https://en.wikiquote.org/wiki/Galileo_Galilei", Text = "This experimentation is the custom—and properly so—in those sciences where mathematical demonstrations are applied to natural phenomena.", Author = "Galileo Galilei" },
            new Quote { Id = "https://en.wikiquote.org/wiki/Galileo_Galilei", Text = "See now the power of truth; the same experiment which at first glance seemed to show one thing, when more carefully examined, assures us of the contrary.", Author = "Galileo Galilei" },
            new Quote { Id = "https://en.wikiquote.org/wiki/Galileo_Galilei", Text = "I wonder not a little how such a question escaped the attention of Archimedes, Apollonius, Euclid and so many other mathematicians and illustrious philosophers, especially since so many ponderous tomes have been devoted to the subject of motion.", Author = "Galileo Galilei" },
            new Quote { Id = "https://en.wikiquote.org/wiki/Galileo_Galilei", Text = "This bounded terminal speed will be called the maximum that such a heavy body can naturally attain through the air...", Author = "Galileo Galilei" },
            new Quote { Id = "https://en.wikiquote.org/wiki/Galileo_Galilei", Text = "I esteem myself happy to have as great an ally as you in my search for truth.", Author = "Galileo Galilei" },
